begin;
create table if not exists services.staff_access(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,user_id uuid not null references authn.users(id),module_code text not null,can_read boolean not null default true,can_write boolean not null default false,granted_by uuid references authn.users(id),created_at timestamptz not null default now(),unique(tenant_id,user_id,module_code));
create table if not exists services.events(id bigint generated always as identity primary key,tenant_id uuid not null references app.tenants(id) on delete cascade,module_code text not null,event_type text not null,entity_type text,entity_id text,actor_id uuid references authn.users(id),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists services.admissions_documents(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,application_id uuid not null references app.admissions_applications(id) on delete cascade,document_type text not null,object_key text not null,original_name text,uploaded_by uuid references authn.users(id),created_at timestamptz not null default now());
create table if not exists services.admissions_offers(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,application_id uuid not null references app.admissions_applications(id) on delete cascade,offer_no text not null,status text not null default 'offered',offered_class_id uuid references academics.classes(id),issued_at timestamptz not null default now(),accepted_at timestamptz,expires_at timestamptz,unique(tenant_id,offer_no));
create table if not exists services.alumni_records(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,alumni_no text not null,student_id uuid references app.students(id),full_name text not null,graduation_year integer,email text,phone text,current_occupation text,profile_user_id uuid references authn.users(id),status text not null default 'active',created_at timestamptz not null default now(),unique(tenant_id,alumni_no));
create table if not exists services.alumni_engagements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,alumni_id uuid not null references services.alumni_records(id) on delete cascade,engagement_type text not null,notes text not null default '',event_date date,created_by uuid references authn.users(id),created_at timestamptz not null default now());
create table if not exists services.alumni_verification_requests(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,alumni_id uuid references services.alumni_records(id),requester_name text not null,requester_email text,status text not null default 'pending',verification_token text not null unique,decided_by uuid references authn.users(id),decided_at timestamptz,created_at timestamptz not null default now());
create table if not exists services.communication_templates(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,name text not null,channel text not null default 'in_app',subject_template text,body_template text not null,active boolean not null default true,created_by uuid references authn.users(id),unique(tenant_id,name));
create table if not exists services.communication_threads(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,subject text not null,thread_type text not null default 'direct',created_by uuid references authn.users(id),created_at timestamptz not null default now(),closed_at timestamptz);
create table if not exists services.communication_thread_participants(tenant_id uuid not null references app.tenants(id) on delete cascade,thread_id uuid not null references services.communication_threads(id) on delete cascade,user_id uuid not null references authn.users(id),joined_at timestamptz not null default now(),left_at timestamptz,primary key(thread_id,user_id));
create table if not exists services.communication_messages(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,thread_id uuid not null references services.communication_threads(id) on delete cascade,sender_id uuid not null references authn.users(id),body text not null,object_keys jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),edited_at timestamptz,deleted_at timestamptz);
create table if not exists services.communication_campaigns(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,name text not null,channel text not null,audience jsonb not null default '{}'::jsonb,template_id uuid references services.communication_templates(id),subject text,body text,status text not null default 'draft',scheduled_at timestamptz,published_at timestamptz,created_by uuid references authn.users(id),created_at timestamptz not null default now());
create table if not exists services.communication_deliveries(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,campaign_id uuid references services.communication_campaigns(id),recipient_user_id uuid references authn.users(id),recipient_address text,channel text not null,status text not null default 'queued',provider_reference text,last_error text,queued_at timestamptz not null default now(),sent_at timestamptz);
create table if not exists services.notification_outbox(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,user_id uuid references authn.users(id),channel text not null,payload jsonb not null,status text not null default 'queued',attempts integer not null default 0,next_attempt_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists services.discipline_incidents(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),incident_date date not null,category text not null,severity text not null default 'moderate',summary text not null,details text not null default '',status text not null default 'open',reported_by uuid references authn.users(id),resolved_by uuid references authn.users(id),resolved_at timestamptz,created_at timestamptz not null default now());
create table if not exists services.discipline_actions(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,incident_id uuid not null references services.discipline_incidents(id) on delete cascade,action_type text not null,details text not null,starts_on date,ends_on date,created_by uuid references authn.users(id),created_at timestamptz not null default now());
create table if not exists services.discipline_guardian_acknowledgements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,incident_id uuid not null references services.discipline_incidents(id) on delete cascade,guardian_id uuid references app.guardians(id),acknowledged_by_user_id uuid references authn.users(id),acknowledged_at timestamptz not null default now(),note text not null default '');
create table if not exists services.welfare_cases(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),case_type text not null,priority text not null default 'normal',summary text not null,status text not null default 'open',assigned_to uuid references authn.users(id),opened_by uuid references authn.users(id),opened_at timestamptz not null default now(),closed_at timestamptz);
create table if not exists services.welfare_case_notes(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,case_id uuid not null references services.welfare_cases(id) on delete cascade,note text not null,confidential boolean not null default true,created_by uuid references authn.users(id),created_at timestamptz not null default now());
create table if not exists services.health_student_profiles(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),blood_group text,allergies text,chronic_conditions text,emergency_notes text,updated_by uuid references authn.users(id),updated_at timestamptz not null default now(),unique(tenant_id,student_id));
create table if not exists services.health_visits(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),visited_at timestamptz not null default now(),complaint text not null,observations text,assessment text,treatment text,disposition text,recorded_by uuid references authn.users(id));
create table if not exists services.health_immunizations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),vaccine text not null,dose text,date_administered date not null,next_due_date date,provider text,recorded_by uuid references authn.users(id));
create table if not exists services.health_medication_administrations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),medication text not null,dose text not null,administered_at timestamptz not null default now(),reason text,administered_by uuid references authn.users(id));
create table if not exists services.hostel_houses(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,code text not null,name text not null,gender_policy text,active boolean not null default true,unique(tenant_id,code));
create table if not exists services.hostel_rooms(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,house_id uuid not null references services.hostel_houses(id) on delete cascade,room_no text not null,capacity integer not null check(capacity>0),active boolean not null default true,unique(house_id,room_no));
create table if not exists services.hostel_beds(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,room_id uuid not null references services.hostel_rooms(id) on delete cascade,bed_no text not null,active boolean not null default true,unique(room_id,bed_no));
create table if not exists services.hostel_allocations(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),bed_id uuid not null references services.hostel_beds(id),academic_year_id uuid references academics.academic_years(id),starts_on date not null,ends_on date,status text not null default 'active',allocated_by uuid references authn.users(id));
create unique index if not exists hostel_one_active_allocation_per_student on services.hostel_allocations(tenant_id,student_id) where status='active';
create table if not exists services.hostel_movements(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid not null references app.students(id),movement_type text not null,movement_at timestamptz not null default now(),destination text,expected_return_at timestamptz,returned_at timestamptz,recorded_by uuid references authn.users(id));
create table if not exists services.hostel_incidents(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references app.tenants(id) on delete cascade,student_id uuid references app.students(id),house_id uuid references services.hostel_houses(id),incident_at timestamptz not null default now(),category text not null,details text not null,status text not null default 'open',reported_by uuid references authn.users(id),resolved_at timestamptz,resolved_by uuid references authn.users(id));

do $$declare t text; begin foreach t in array array['staff_access','events','admissions_documents','admissions_offers','alumni_records','alumni_engagements','alumni_verification_requests','communication_templates','communication_threads','communication_thread_participants','communication_messages','communication_campaigns','communication_deliveries','notification_outbox','discipline_incidents','discipline_actions','discipline_guardian_acknowledgements','welfare_cases','welfare_case_notes','health_student_profiles','health_visits','health_immunizations','health_medication_administrations','hostel_houses','hostel_rooms','hostel_beds','hostel_allocations','hostel_movements','hostel_incidents'] loop perform app.install_tenant_policy('services',t,true); end loop; end$$;

do $$begin if exists(select 1 from pg_roles where rolname='edusentia_runtime') then grant select,insert,update,delete on all tables in schema services to edusentia_runtime; grant usage,select on all sequences in schema services to edusentia_runtime; end if; end$$;
insert into app.schema_migrations(version) values ('0010_student_services') on conflict do nothing;
update app.release_identity set schema_version='0010' where edition='Edusentia Enterprise Neon Edition';
commit;
